def merge_sorted_streams(*streams):
    def merge(key, values):
        i = 0
        while i < len(values):
            for stream in streams:
                if key in stream and stream[i] == key:
                    i += 1
                    break
            else:
                yield (key, values[i])
                i += 1

    result = []
    for key, values in sorted(streams, key=lambda x: (sorted(x).keys(), x)):
        merged = []
        for v in values:
            merged.append(v)
        result.extend(merge_sorted_streams(merged))
    return result
